public:
    long long maxScore(vector<int>& nums) {
        int n = nums.size();
        if (n == 1) return (long long)nums[0] * nums[0];

        auto gcd_fn = [](long long a, long long b) {
            return std::gcd(a, b);
        };
        auto lcm_fn = [&](long long a, long long b) {
            return (a / std::gcd(a, b)) * b;
        };

        vector<long long> pref_gcd(n), pref_lcm(n);
        vector<long long> suff_gcd(n), suff_lcm(n);

        pref_gcd[0] = pref_lcm[0] = nums[0];
        for (int i = 1; i < n; ++i) {
            pref_gcd[i] = gcd_fn(pref_gcd[i - 1], nums[i]);
            pref_lcm[i] = lcm_fn(pref_lcm[i - 1], nums[i]);
        }

        suff_gcd[n - 1] = suff_lcm[n - 1] = nums[n - 1];
        for (int i = n - 2; i >= 0; --i) {
            suff_gcd[i] = gcd_fn(suff_gcd[i + 1], nums[i]);
            suff_lcm[i] = lcm_fn(suff_lcm[i + 1], nums[i]);
        }

