class Solution {
    public long maxScore(int[] nums) {
        int n = nums.length;
        if (n == 1) return (long) nums[0] * nums[0];

        long[] prefGcd = new long[n];
        long[] prefLcm = new long[n];
        long[] suffGcd = new long[n];
        long[] suffLcm = new long[n];

        prefGcd[0] = prefLcm[0] = nums[0];
        for (int i = 1; i < n; i++) {
            prefGcd[i] = gcd(prefGcd[i - 1], nums[i]);
            prefLcm[i] = lcm(prefLcm[i - 1], nums[i]);
        }

        suffGcd[n - 1] = suffLcm[n - 1] = nums[n - 1];
        for (int i = n - 2; i >= 0; i--) {
            suffGcd[i] = gcd(suffGcd[i + 1], nums[i]);
            suffLcm[i] = lcm(suffLcm[i + 1], nums[i]);
        }

        long best = prefGcd[n - 1] * prefLcm[n - 1];
        for (int i = 0; i < n; i++) {
            long g, l;
            if (i == 0) {
                g = suffGcd[1];
                l = suffLcm[1];
            } else if (i == n - 1) {
                g = prefGcd[n - 2];
                l = prefLcm[n - 2];
            } else {
                g = gcd(prefGcd[i - 1], suffGcd[i + 1]);
                l = lcm(prefLcm[i - 1], suffLcm[i + 1]);
            }
            best = Math.max(best, g * l);
        }
        return best;
    }

    private long gcd(long a, long b) {
        while (b != 0) {
            long t = b;
            b = a % b;
            a = t;
        }
        return a;
    }

    private long lcm(long a, long b) {
        return (a / gcd(a, b)) * b;
    }
}

var maxScore = function(nums) {
    const n = nums.length;
    if (n === 1) return nums[0] * nums[0];

    function gcd(a, b) {
        a = BigInt(a); b = BigInt(b);
        while (b !== 0n) {
            const t = b;
            b = a % b;
            a = t;
        }
        return a;
    }

    function lcm(a, b) {
        a = BigInt(a); b = BigInt(b);
        return (a / gcd(a, b)) * b;
    }

    const prefGcd = new Array(n);
    const prefLcm = new Array(n);
    const suffGcd = new Array(n);
    const suffLcm = new Array(n);

    prefGcd[0] = prefLcm[0] = BigInt(nums[0]);
    for (let i = 1; i < n; i++) {
        prefGcd[i] = gcd(prefGcd[i - 1], nums[i]);
        prefLcm[i] = lcm(prefLcm[i - 1], nums[i]);
    }

    suffGcd[n - 1] = suffLcm[n - 1] = BigInt(nums[n - 1]);
    for (let i = n - 2; i >= 0; i--) {
        suffGcd[i] = gcd(suffGcd[i + 1], nums[i]);
        suffLcm[i] = lcm(suffLcm[i + 1], nums[i]);
    }

    let best = prefGcd[n - 1] * prefLcm[n - 1];
    for (let i = 0; i < n; i++) {
        let g, l;
        if (i === 0) {
            g = suffGcd[1];
            l = suffLcm[1];
        } else if (i === n - 1) {
            g = prefGcd[n - 2];
            l = prefLcm[n - 2];
        } else {
            g = gcd(prefGcd[i - 1], suffGcd[i + 1]);
            l = lcm(prefLcm[i - 1], suffLcm[i + 1]);
        }
        const candidate = g * l;
        if (candidate > best) best = candidate;
    }
    return Number(best);
};
